\end{align*}
Now, we can subtract equation (3) from equation (1) to eliminate $u$:
\begin{align*}
(4u - 5v) - (4u + 8v) &= 23 - (-16) \\
4u - 5v - 4u - 8v &= 39 \\
-13v &= 39 \\
v &= -3
\end{align*}
